//! Desktop client code generation for the Rust shell.
//!
//! Emits the `src/bin/desktop.rs` entry point that launches the native egui
//! desktop client using `orbital_client::run_desktop`.

/// Generate the `src/bin/desktop.rs` source for the generated application.
pub fn generate_desktop_bin() -> String {
    r#"//! Native desktop client entry point.
//!
//! Generated by the Orbital Rust shell. Run with:
//!   cargo run --bin desktop
//!
//! The desktop client communicates with the Orbital server (default
//! http://127.0.0.1:3030) using the closed-circuit event protocol.

use std::path::Path;

fn main() -> anyhow::Result<()> {
    let server_url = std::env::var("SERVER_URL")
        .ok()
        .or_else(|| Some("http://127.0.0.1:3030".to_string()));

    orbital_client::run_desktop(Path::new("resolved.orb"), server_url.as_deref())
}
"#
    .to_string()
}
